{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/bento-grid.json
    Tiles of different sizes in one grid: the large and wide tiles hold the important features. Sizes come from the data (large, wide, small). Axes: layout (bento, even: all tiles alike), media (none, image: a picture in the large tiles), tone, density.
    Props (p): id, title, tiles, empty, layout, media, tone, density, landmarkLabel. *}
{var $k_SPAN = ['large' => 'md:col-span-2 md:row-span-2', 'wide' => 'md:col-span-2', 'small' => '']}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_tiles = ($p['tiles'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_layout = ($p['layout'] ?? 'bento')}
{var $v_media = ($p['media'] ?? 'none')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_6}
  {if og_t(og_eq(og_len($v_tiles), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'layout-dashboard', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_5}
      {foreach og_l($v_tiles) as $v_tile}
        {capture $c_4}
          {capture $c_3}
            {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_tile, ['icon'])), 'size' => 24])|noescape}
            {capture $c_1}
              {=og_text(og_get($v_tile, ['title']))}
            {/capture}
            {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'xl', 'weight' => 'bold', 'children' => (string) $c_1])|noescape}
            {capture $c_2}
              {=og_text(og_get($v_tile, ['text']))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
            {if og_t(og_and([og_eq($v_media, 'image'), og_or([og_eq(og_get($v_tile, ['size']), 'large'), og_eq($v_layout, 'even')])]))}
              {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_tile, ['title']), 'ratio' => '4/3', 'className' => og_cnv(['mt-auto'])]])|noescape}
            {/if}
          {/capture}
          {=og_include('compose/CardContent.latte', ['class' => 'flex h-full flex-col gap-4', 'children' => (string) $c_3])|noescape}
        {/capture}
        {=og_include('compose/Card.latte', ['variant' => 'default', 'class' => og_s(og_cnv(['h-full overflow-hidden', (og_t(og_eq($v_density, 'compact')) ? 'gap-4 p-4' : ''), (og_t(og_eq($v_layout, 'bento')) ? og_at($k_SPAN, og_get($v_tile, ['size'])) : '')])), 'attrs' => og_attrs(['data-testid', 'item', 'data-size', (og_t(og_eq($v_layout, 'bento')) ? og_get($v_tile, ['size']) : 'even')]), 'children' => (string) $c_4])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => '1-4', 'class' => 'auto-rows-fr gap-4', 'attrs' => og_attrs(['data-testid', 'items']), 'children' => (string) $c_5])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_6)])|noescape}
